const sharp = require('sharp');
const fs = require('fs');
const path = require('path');
const express = require('express');
const router = express.Router();

router.get('/thumb/:size/:name', async (req, res) => {
  const size = Math.min(2048, parseInt(req.params.size) || 256);
  const cachePath = path.join('{{cache_dir}}', `${size}-${req.params.name}`);
  if (fs.existsSync(cachePath)) return res.sendFile(path.resolve(cachePath));
  const src = path.join('uploads', req.params.name);
  if (!fs.existsSync(src)) return res.status(404).end();
  await sharp(src).resize(size, size, { fit: 'inside' }).toFile(cachePath);
  res.sendFile(path.resolve(cachePath));
});

module.exports = router;
